"use strict";

// The same-NAME, same-VERSION twin of the vulnerable `fixture-lib`,
// installed at a DIFFERENT location. Its code carries no defect at all:
// there is no throwing local callable and no conditional export, so its
// whole-module export is a plain, unconditional fact.
//
// It exists so that "which install did this finding come from" is a
// question the fixture can actually ask. A model that collapsed package
// identity by name+version would happily attribute this instance's
// harmless export to the vulnerable instance's finding, or vice versa.
function twinOp(input) {
  return "twin:" + input;
}

module.exports = twinOp;
